// Score Skool communities by Estimated Monthly Recurring Revenue (MRR), affiliate %, and creator reachability
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const members = Number(j.total_members || j.members || 0);
  const price = Number(j.monthly_price_usd || j.price || 0);
  const estMrr = Number(j.estimated_mrr_usd || (members * price));
  let score = 30;
  const signals = [];
  if (estMrr >= 10000) {
    score += 35;
    signals.push(`$${Math.round(estMrr).toLocaleString()}/mo Est MRR`);
  } else if (estMrr > 0) {
    score += 15;
    signals.push(`Paid Community ($${price}/mo)`);
  }
  if (j.creator_youtube || j.creator_instagram || j.creator_twitter || j.creator_website) {
    score += 20;
    signals.push('Creator Socials Enriched');
  }
  if (Number(j.affiliate_commission_pct || 0) >= 20) {
    score += 15;
    signals.push(`${j.affiliate_commission_pct}% Affiliate Program`);
  }
  out.push({
    json: {
      ...j,
      estimated_mrr_usd: Math.round(estMrr),
      lead_score: Math.min(100, score),
      priority_tier: score >= 70 ? 'Tier 1 — $10k+ MRR Creator' : 'Tier 2 — Growing Group',
      scoring_signals: signals.join(' | ') || 'Community Record',
      scored_at: new Date().toISOString()
    }
  });
}
return out;

